private boolean createOrUpdatePricingRuleCondition(GUPPricingRuleCondition _ruleCondition, RefRecId _ruleId, GUPRefRecId _conditionAttribute, AttributeValueText _value, str _fieldName)
{
    if (_ruleCondition)
    {
        _ruleCondition.ConditionAttribute = _conditionAttribute;
        _ruleCondition.ConditionValue = _value;
        if (!_ruleCondition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        _ruleCondition.update();
    }
    else
    {
        _ruleCondition.RuleId = _ruleId;
        _ruleCondition.ConditionAttribute = _conditionAttribute;
        _ruleCondition.ConditionValue = _value;
        if (!_ruleCondition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        _ruleCondition.insert();
    }
    return true;
}

private GUPPriceComponentCodePriceAttributeGroupCombination getPriceAttributeGroupCombination()
{
    GUPPriceComponentCode componentCode;
    select firstonly componentCode where componentCode.RelationType == GUPPriceComponent::SalesTradeAgreement;
    GUPPriceComponentCodePriceAttributeGroupCombination combination = GUPPriceComponentCodePriceAttributeGroupCombination::findByNameAndComponentCode(this.PriceComponentCombination, componentCode, true);
    if (!combination)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPPriceComponentCodePriceAttributeGroupCombination_NotExisting", this.PriceComponentCombination));
    }
    return  combination;
}

private void removeRuleConditions(GUPPricingRule _rule)
{
    GUPPricingRuleCondition condition;
    delete_from condition where condition.RuleId == _rule.RecId;
}

public void postLoad()
{
    next postLoad();
    if (this.PricingRuleHeader)
    {
        GUPPricingRule pricingRule = GUPPricingRule::find(this.PricingRuleHeader);
        if (pricingRule.PriceAttributeGroupName)
        {
            int num = 1;
            str baseFieldName = 'Header';
            GUPPricingRuleCondition ruleCondition;
            GUPPricingAttributeLink attributeLink;
            while select ruleCondition 
                where ruleCondition.RuleId == this.PricingRuleHeader 
                join attributeLink 
                    order by attributeLink.Priority asc
                    where ruleCondition.ConditionAttribute == attributeLink.RecId
            {
                this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
                num++;
            }
        }
    }

    if (this.PricingRuleLine)
    {
        GUPPricingRule pricingRule = GUPPricingRule::find(this.PricingRuleLine);
        if (pricingRule.PriceAttributeGroupName)
        {
            int num = 1;
            str baseFieldName = 'Line';
            GUPPricingRuleCondition ruleCondition;
            GUPPricingAttributeLink attributeLink;
            while select ruleCondition
                where ruleCondition.RuleId == this.PricingRuleLine
                join attributeLink
                    order by attributeLink.Priority asc
                    where ruleCondition.ConditionAttribute == attributeLink.RecId
            {
                this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
                num++;
            }
        }
    }
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(SalesOpenSalesPriceJournalLineEntity, PriceDiscAdmTrans))
    {
        PriceDiscAdmTrans trans = _dataSourceCtx.getBuffer();
        trans.ItemCode = PriceDiscProductCodeType::Table;

        if (this.PriceComponentCombination)
        {
            PriceDiscAdmTable journal = PriceDiscAdmTable::find(trans.JournalNum);
            PriceDiscAdmName journalName = PriceDiscAdmName::find(journal.JournalName);
            if (!journalName.PriceDiscPriceAttributeEnable)
            {
                throw error(strfmt("@GlobalUnifiedPricing:PriceDiscAdmName_AttributeNotEnabled", journalName.JournalName));
            }
            GUPPriceComponentCodePriceAttributeGroupCombination combination = this.getPriceAttributeGroupCombination();
            trans.PriceComponentCombination = combination.RecId;

            GUPPricingRule headerRule = GUPPricingRule::newPricingRule(combination.HeaderPriceAttributeGroupName, GUPPricingRuleExclusionType::Customer);
            trans.PricingRuleHeader = headerRule.RecId;
            // insert header pricing rule condition
            if (combination.HeaderPriceAttributeGroupName)
            {
                ttsbegin;
                int num = 1;
                str baseFieldName = 'Header';
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.HeaderPriceAttributeGroupName
                {
                    this.createOrUpdatePricingRuleCondition(null, headerRule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }

            GUPPricingRule lineRule = GUPPricingRule::newPricingRule(combination.LinePriceAttributeGroupName, GUPPricingRuleExclusionType::Product);
            trans.PricingRuleLine = lineRule.RecId;
            // insert line pricing rule condition
            if (combination.LinePriceAttributeGroupName)
            {
                ttsbegin;
                int num = 1;
                str baseFieldName = 'Line';
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.LinePriceAttributeGroupName
                {
                    this.createOrUpdatePricingRuleCondition(null, lineRule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }
        }
    }
    ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);
    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(SalesOpenSalesPriceJournalLineEntity, PriceDiscAdmTrans))
    {
        PriceDiscAdmTrans trans = _dataSourceCtx.getBuffer();
        trans.ItemCode = PriceDiscProductCodeType::Table;

        if (this.PriceComponentCombination)
        {
            PriceDiscAdmTable journal = PriceDiscAdmTable::find(trans.JournalNum);
            PriceDiscAdmName journalName = PriceDiscAdmName::find(journal.JournalName);
            if (!journalName.PriceDiscPriceAttributeEnable)
            {
                throw error(strfmt("@GlobalUnifiedPricing:PriceDiscAdmName_AttributeNotEnabled", journalName.JournalName));
            }
            GUPPriceComponentCodePriceAttributeGroupCombination combination = this.getPriceAttributeGroupCombination();
            trans.PriceComponentCombination = combination.RecId;

            GUPPricingRule headerRule = GUPPricingRule::find(trans.PricingRuleHeader, true);
            GUPPricingRule lineRule = GUPPricingRule::find(trans.PricingRuleLine, true);

            if (combination.HeaderPriceAttributeGroupName)
            {
                // insert/update header pricing rule condition
                ttsbegin;
                if (headerRule.PriceAttributeGroupName != combination.HeaderPriceAttributeGroupName)
                {
                    headerRule.selectForUpdate(true);
                    headerRule.delete();
                    headerRule = null;
                }

                if (!headerRule)
                {
                    headerRule = GUPPricingRule::newPricingRule(combination.HeaderPriceAttributeGroupName, GUPPricingRuleExclusionType::Customer);
                    trans.PricingRuleHeader = headerRule.RecId;
                }
                int num = 1;
                str baseFieldName = 'Header';
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.HeaderPriceAttributeGroupName
                {
                    GUPPricingRuleCondition ruleCondition = GUPPricingRuleCondition::find(headerRule.RecId, attributeLink.RecId, true);
                    this.createOrUpdatePricingRuleCondition(ruleCondition, headerRule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }
            else
            {
                ttsbegin;
                this.removeRuleConditions(headerRule);
                headerRule.PriceAttributeGroupName = null;
                headerRule.update();
                ttscommit;
            }

            if (combination.LinePriceAttributeGroupName)
            {
                // insert/update header pricing rule condition
                ttsbegin;
                if (lineRule.PriceAttributeGroupName != combination.LinePriceAttributeGroupName)
                {
                    lineRule.selectForUpdate(true);
                    lineRule.delete();
                    lineRule = null;
                }

                if (!lineRule)
                {
                    lineRule = GUPPricingRule::newPricingRule(combination.LinePriceAttributeGroupName, GUPPricingRuleExclusionType::Product);
                    trans.PricingRuleLine = lineRule.RecId;
                }
                int num = 1;
                str baseFieldName = 'Line';
                GUPPricingAttributeLink attributeLink;
                while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == combination.LinePriceAttributeGroupName
                {
                    GUPPricingRuleCondition ruleCondition = GUPPricingRuleCondition::find(lineRule.RecId, attributeLink.RecId, true);
                    this.createOrUpdatePricingRuleCondition(ruleCondition, lineRule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                    num ++;
                }
                ttscommit;
            }
            else
            {
                ttsbegin;
                this.removeRuleConditions(lineRule);
                lineRule.PriceAttributeGroupName = null;
                lineRule.update();
                ttscommit;
            }
        }
        else
        {
            trans.PricingRuleHeader = 0;
            trans.PricingRuleLine = 0;
        }
    }
    ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);
    return ret;
}

public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next initializeEntityDataSource(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() ==  dataEntityDataSourceStr(SalesOpenSalesPriceJournalLineEntity, GUPPriceComponentCodePriceAttributeGroupCombination))
    {
        _dataSourceCtx.setDataSaved(true);
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
    }
}
